/**
 * rules.test.ts — the TS mirror must agree with the Python engine on every
 * shared test vector (data/test-vectors.json, generated by the pipeline),
 * plus unit checks on the number parser.
 */
import { describe, expect, it } from "vitest";
import { assessClause, normalizeNumbers, parseDays, parseMonths, routeForClause } from "./rules";
import vectorsJson from "../public/data/test-vectors.json";
import summaryJson from "../public/data/summary.json";

const THRESHOLDS = summaryJson.config.thresholds;

describe("shared test vectors (Python/TS contract)", () => {
  it("has one vector per playbook rule", () => {
    expect(vectorsJson.vectors).toHaveLength(12);
    expect(new Set(vectorsJson.vectors.map((v) => v.rule_id)).size).toBe(12);
  });

  for (const v of vectorsJson.vectors) {
    it(`${v.rule_id} (${v.contract_id}) agrees: ${v.expected_tier} ${v.expected_score}`, () => {
      const got = assessClause(v.rule_id, v.term_spans, THRESHOLDS, v.has_exception, v.notice_spans);
      expect(got.tier).toBe(v.expected_tier);
      expect(got.score).toBe(v.expected_score);
    });
  }
});

describe("number parsing", () => {
  it("normalizes written-out numbers and parenthetical restatements", () => {
    expect(normalizeNumbers("three (3) months written notice")).toBe("3 months written notice");
    expect(normalizeNumbers("sixty (60) days prior")).toBe("60 days prior");
    expect(normalizeNumbers("twelve-month period")).toBe("12-month period");
    expect(normalizeNumbers("twenty four (24) months")).toBe("24 months");
  });

  it("parses months and days", () => {
    expect(parseMonths(normalizeNumbers("limited to twelve-month fees"))).toBe(12);
    expect(parseMonths(normalizeNumbers("for one (1) year terms"))).toBe(12);
    expect(parseMonths(normalizeNumbers("renew for two (2) years"))).toBe(24);
    expect(parseDays(normalizeNumbers("thirty days written notice"))).toBe(30);
    expect(parseDays(normalizeNumbers("five days prior written notice"))).toBe(5);
    expect(parseDays(normalizeNumbers("three (3) months notice"))).toBe(90);
    expect(parseDays(normalizeNumbers("no period stated"))).toBeNull();
  });
});

describe("clause rules", () => {
  it("12-month cap accepts, 6-month cap flags, amount-only flags", () => {
    expect(assessClause("LIABILITY_CAP", ["limited to the amounts paid or payable during the twelve-month period"], THRESHOLDS).tier).toBe("ACCEPT");
    expect(assessClause("LIABILITY_CAP", ["liability capped at six months fees"], THRESHOLDS).score).toBe(73);
    expect(assessClause("LIABILITY_CAP", ["liability shall not exceed U.S.$5,000,000"], THRESHOLDS).score).toBe(60);
  });

  it("Ontario accepts, US states flag at 80", () => {
    expect(assessClause("GOVERNING_LAW", ["governed by the laws of the Province of Ontario, Canada"], THRESHOLDS).tier).toBe("ACCEPT");
    expect(assessClause("GOVERNING_LAW", ["governed by the laws of the State of New York"], THRESHOLDS).score).toBe(80);
  });

  it("MFN rejects and routes to ESCALATE", () => {
    const a = assessClause("MFN", ["terms no less favourable than any reseller"], THRESHOLDS);
    expect(a.tier).toBe("REJECT");
    expect(routeForClause(a)).toBe("ESCALATE");
  });

  it("anti-assignment: consent-required flags, freely assignable accepts", () => {
    expect(assessClause("ANTI_ASSIGNMENT", ["No assignment shall be made without the prior written consent of the Company"], THRESHOLDS).score).toBe(60);
    expect(assessClause("ANTI_ASSIGNMENT", ["Either party may freely assign this Agreement to an affiliate"], THRESHOLDS).tier).toBe("ACCEPT");
  });

  it("auto-renewal never reads the term as a notice period", () => {
    const ok = assessClause("AUTO_RENEWAL", ["renew for one (1) year terms"], THRESHOLDS, false, ["sixty (60) days prior notice"]);
    expect(ok.tier).toBe("ACCEPT");
    const longTerm = assessClause("AUTO_RENEWAL", ["renew for an additional two (2) years"], THRESHOLDS, false, ["sixty (60) days prior notice"]);
    expect(longTerm.score).toBe(79);
  });

  it("absent audit rights flag; absent MFN accepts", () => {
    expect(assessClause("AUDIT_RIGHTS", [], THRESHOLDS).tier).toBe("FLAG");
    expect(assessClause("MFN", [], THRESHOLDS).tier).toBe("ACCEPT");
  });
});
